<template>
  <div class="app-container creators">
    <div class="heading"><div><h2>创作者管理</h2><p>开通账号，设置创作资格、资源范围和正式点数。</p></div><el-tag type="info">用户权益 · 第 4 步</el-tag></div>
    <el-alert title="正式点数独立记账" description="新账号初始点数为 0，没有模型授权。配置模型范围并发放点数后，用户在创作端确认报价执行；旧测试额度和 qwen 记录独立保留。" type="info" :closable="false" show-icon />
    <el-alert v-if="pending" title="有一项操作待确认" type="warning" :closable="false" class="notice"><p>{{ labels[pending.op] }} · {{ pending.requestId }}</p><p>只保存操作编号、目标与版本。请先核对；重试须重新填写原内容，密码不保存在浏览器。</p><el-button :loading="checking" @click="checkPending">核对原操作</el-button><el-button :disabled="saving" @click="recoverPending">重填原操作</el-button></el-alert>
    <el-alert v-if="error" :title="error" type="error" :closable="false" class="notice" />
    <el-alert v-if="limits && !limits.writesReady" title="独立主密钥未就绪，当前只读。" type="warning" :closable="false" class="notice" />
    <el-form inline class="query" @submit.prevent="search"><el-form-item label="账号 / 昵称"><el-input v-model="query.name" maxlength="100" clearable /></el-form-item><el-form-item label="资格"><el-select v-model="query.status" clearable placeholder="全部" style="width:130px"><el-option label="已开通" value="active" /><el-option label="已停用" value="suspended" /></el-select></el-form-item><el-form-item><el-button type="primary" :loading="loading" @click="search">查询</el-button><el-button v-if="has('podAdmin:creator:add')" :disabled="blocked" @click="open('creator.create')">开通创作者</el-button></el-form-item></el-form>
    <el-table v-loading="loading" :data="rows" empty-text="暂无创作者，可先开通账号。">
      <el-table-column label="账号 / 昵称" min-width="170"><template #default="{row}"><strong>{{ row.userName }}</strong><div class="muted">{{ row.nickName }} · #{{ row.userId }}</div></template></el-table-column>
      <el-table-column label="资格" min-width="120"><template #default="{row}"><el-tag :type="row.accountStatus !== '0' || row.status === 'suspended' ? 'info' : row.expired ? 'warning' : 'success'">{{ row.accountStatus !== '0' ? '账号已停用' : row.status === 'suspended' ? '资格已停用' : row.expired ? '已到期 · 只读' : '已开通' }}</el-tag></template></el-table-column>
      <el-table-column label="有效期（北京时间）" min-width="170"><template #default="{row}">{{ date(row.validUntil) }}</template></el-table-column>
      <el-table-column label="资源上限" min-width="220"><template #default="{row}">并发 {{ row.maxConcurrentNodes }} · 待执行 {{ row.maxPendingRuns }}<div class="muted">每日 {{ row.maxDailySubmissions }} 次 · {{ formatBytes(row.maxStorageBytes) }}</div></template></el-table-column>
      <el-table-column label="操作" min-width="250"><template #default="{row}"><el-button v-if="has('podAdmin:creator:query')" link type="primary" @click="showDetail(row.userId)">详情</el-button><el-button v-if="has('podAdmin:creator:edit')" link type="primary" :disabled="blocked" @click="open('creator.policy',row)">权益</el-button><el-button v-if="has('podAdmin:creator:grant') && has('podAdmin:creator:query')" link type="primary" :disabled="blocked" @click="openModels(row.userId)">模型范围</el-button><el-button v-if="has('podAdmin:points:adjust') && has('podAdmin:points:query')" link type="primary" :disabled="blocked" @click="openPoints(row.userId)">调整点数</el-button></template></el-table-column>
    </el-table>
    <pagination v-show="total > 0 && !error" v-model:page="page" v-model:limit="size" :total="total" @pagination="loadList" />
    <el-dialog v-model="detailOpen" title="创作者详情" width="860px">
      <el-alert v-if="detailError" :title="detailError" type="error" :closable="false" />
      <div v-loading="detailLoading" class="detail"><template v-if="detail">
        <h3>{{ detail.creator.nickName }} <small class="muted">{{ detail.creator.userName }} · #{{ detail.creator.userId }}</small></h3>
        <el-tabs v-model="detailTab" @tab-change="loadDetailTab">
          <el-tab-pane label="权益与存储" name="policy"><el-descriptions :column="2" border><el-descriptions-item label="资格">{{ detail.creator.status === 'active' ? detail.creator.expired ? '已到期 · 只读' : '已开通' : '已停用' }}</el-descriptions-item><el-descriptions-item label="有效期">{{ date(detail.creator.validUntil) }}</el-descriptions-item><el-descriptions-item label="并发 / 待执行">{{ detail.creator.maxConcurrentNodes }} / {{ detail.creator.maxPendingRuns }}</el-descriptions-item><el-descriptions-item label="今日次数">{{ detail.dailySubmissions }} / {{ detail.creator.maxDailySubmissions }}（{{ detail.businessDate }}）</el-descriptions-item><el-descriptions-item label="已用空间">{{ formatBytes(detail.storage.usedBytes) }}</el-descriptions-item><el-descriptions-item label="预留空间">{{ formatBytes(detail.storage.heldBytes) }}</el-descriptions-item><el-descriptions-item label="空间上限">{{ formatBytes(detail.creator.maxStorageBytes) }}</el-descriptions-item><el-descriptions-item label="权益版本">{{ detail.creator.revision }}</el-descriptions-item></el-descriptions><p class="muted">失败和取消不返还当日次数；空间包含原图、缩略图、派生图及回收站。预留中的文件需精确核对后处理。</p></el-tab-pane>
          <el-tab-pane label="模型范围" name="models"><p>{{ detail.modelIds.length ? `已授权模型 ID：${detail.modelIds.join('、')}` : '未授权模型' }}</p><p class="muted">此范围用于正式模型执行；模型和供应商的启停仍独立生效，撤权后尚未提交的调用会被阻止。</p></el-tab-pane>
          <el-tab-pane v-if="has('podAdmin:points:query')" label="点数与流水" name="points"><template v-if="points"><el-descriptions :column="3" border><el-descriptions-item label="可用">{{ points.available }}</el-descriptions-item><el-descriptions-item label="预占">{{ points.held }}</el-descriptions-item><el-descriptions-item label="已用">{{ points.spent }}</el-descriptions-item></el-descriptions><el-table :data="events" class="notice"><el-table-column label="操作" width="90"><template #default="{row}">{{ pointEventLabel(row.kind) }}</template></el-table-column><el-table-column prop="amount" label="点数" /><el-table-column prop="availableAfter" label="操作后可用" /><el-table-column prop="reason" label="原因" min-width="150" show-overflow-tooltip /><el-table-column label="时间" min-width="170"><template #default="{row}">{{ date(row.createTime) }}</template></el-table-column></el-table><pagination v-show="eventTotal > 0" v-model:page="eventPage" v-model:limit="eventSize" :total="eventTotal" @pagination="loadPoints" /></template></el-tab-pane>
        </el-tabs>
      </template></div>
    </el-dialog>
    <el-dialog v-model="dialog" :title="labels[op]" width="690px" :close-on-click-modal="false" :before-close="closeDialog" @closed="clearPassword">
      <el-alert v-if="formError" :title="formError" type="error" :closable="false" class="notice" />
      <el-form label-width="130px" @submit.prevent="submit">
        <template v-if="op === 'creator.create'"><el-form-item label="登录账号" required><el-input v-model="form.userName" maxlength="20" autocomplete="off" placeholder="3—20 位，字母开头，可含数字和 _-" /></el-form-item><el-form-item label="昵称" required><el-input v-model="form.nickName" maxlength="30" /></el-form-item><el-form-item label="初始密码" required><el-input v-model="form.initialPassword" type="password" maxlength="20" autocomplete="new-password" placeholder="8—20 字，不保存或回显" /></el-form-item></template>
        <template v-if="op === 'creator.create' || op === 'creator.policy'">
          <el-form-item label="资格状态" required><el-radio-group v-model="form.status"><el-radio value="active">开通</el-radio><el-radio value="suspended">停用</el-radio></el-radio-group><div class="hint muted">到期可查看和下载；停用阻止私有内容读写，不会删除文件或重复调用模型。</div></el-form-item>
          <el-form-item label="到期时间"><el-date-picker v-model="form.validUntil" type="datetime" value-format="YYYY-MM-DD HH:mm:ss" placeholder="北京时间，留空为长期有效" style="width:100%" /></el-form-item>
          <el-form-item label="同时执行节点" required><el-input-number v-model="form.maxConcurrentNodes" :min="1" :max="limits?.maxConcurrentNodes || 1" :precision="0" /><span class="inline-hint">实例上限 {{ limits?.maxConcurrentNodes }}</span></el-form-item>
          <el-form-item label="待执行数" required><el-input-number v-model="form.maxPendingRuns" :min="1" :max="limits?.maxPendingRuns || 1" :precision="0" /><span class="inline-hint">实例上限 {{ limits?.maxPendingRuns }}</span></el-form-item>
          <el-form-item label="每日提交次数" required><el-input-number v-model="form.maxDailySubmissions" :min="1" :max="10000" :precision="0" /></el-form-item>
          <el-form-item label="存储上限 / 字节" required><el-input v-model="form.maxStorageBytes" inputmode="numeric" maxlength="11" /><div class="hint muted">{{ storagePreview(form.maxStorageBytes) }}；最多 10 GiB。下调不删除文件，超限时阻止新增。</div></el-form-item>
        </template>
        <el-form-item v-if="op === 'creator.models'" label="允许的模型"><el-select v-model="form.modelIds" multiple filterable remote :remote-method="searchModels" :loading="optionsLoading" style="width:100%" placeholder="输入名称搜索，最多 100 项"><el-option v-for="item in options" :key="item.modelId" :value="item.modelId" :label="`${item.name} · #${item.modelId}${item.status !== 'enabled' || item.providerStatus !== 'enabled' ? '（已停用）' : ''}`" /></el-select><div class="hint muted">空数组表示不授权模型。已选项不会因搜索而丢失。</div></el-form-item>
        <template v-if="op === 'points.adjust'"><el-alert :title="`当前可用 ${form.available} 点；预占部分不能扣减。`" type="info" :closable="false" class="notice" /><el-form-item label="操作" required><el-radio-group v-model="form.kind"><el-radio value="grant">发放</el-radio><el-radio value="deduct">扣减</el-radio></el-radio-group></el-form-item><el-form-item label="点数" required><el-input v-model="form.amount" inputmode="numeric" maxlength="10" placeholder="1—1000000000 的整数" /></el-form-item></template>
        <el-form-item label="操作原因" required><el-input v-model="form.reason" maxlength="200" placeholder="填写业务原因，不要填密码或密钥" /></el-form-item>
      </el-form>
      <template #footer><el-button :disabled="saving" @click="clearPassword();dialog=false">取消</el-button><el-button type="primary" :loading="saving" :disabled="!limits?.writesReady" @click="submit">{{ pending ? '沿用原编号提交' : '确认保存' }}</el-button></template>
    </el-dialog>
  </div>
</template>
<script setup>
import { computed, onBeforeUnmount, onMounted, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import useUserStore from '@/store/modules/user'
import { catalogList, catalogGet, catalogWrite, catalogAction } from '@/api/pod/admin'
import { formatBytes } from '@/utils/pod-admin'
import { creatorPayload, creatorPending, readCreatorPending, pointEventLabel } from '@/utils/pod-creator'
const user=useUserStore(), has=p=>user.podAdmin?.permissions?.includes(p)
const labels={'creator.create':'开通创作者','creator.policy':'修改创作权益','creator.models':'设置模型范围','points.adjust':'调整正式点数'}
const query=reactive({name:'',status:''}), rows=ref([]), total=ref(0), page=ref(1), size=ref(10), loading=ref(false), error=ref(''), limits=ref(null)
const dialog=ref(false), op=ref(''), form=ref({}), formError=ref(''), saving=ref(false), checking=ref(false), pending=ref(null), options=ref([]), optionsLoading=ref(false)
const detailOpen=ref(false), detail=ref(null), detailLoading=ref(false), detailError=ref(''), detailTab=ref('policy'), points=ref(null), events=ref([]), eventTotal=ref(0), eventPage=ref(1), eventSize=ref(10)
const pendingKey=`pod-admin.creator.pending.${user.id}`
try{pending.value=readCreatorPending(sessionStorage.getItem(pendingKey))}catch{error.value='浏览器操作编号不可读；提交前需要恢复浏览器存储。'}
const blocked=computed(()=>!limits.value?.writesReady || !!pending.value || saving.value)
let listSeq=0, detailSeq=0, pointsSeq=0, optionSeq=0
function storagePreview(v){try{return formatBytes(v || '0')}catch{return '请输入正整数'}}
function date(v){return v?new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai',dateStyle:'short',timeStyle:'medium'}).format(new Date(v)):'长期有效'}
async function loadList(){const seq=++listSeq;loading.value=true;error.value='';rows.value=[];try{const r=await catalogList('creators',{...query,pageNum:page.value,pageSize:size.value});if(seq===listSeq){rows.value=r.rows;total.value=r.total}}catch(e){if(seq===listSeq)error.value=e.message}finally{if(seq===listSeq)loading.value=false}}
function search(){page.value=1;loadList()}
async function showDetail(id){const seq=++detailSeq;detailOpen.value=true;detailLoading.value=true;detail.value=null;points.value=null;events.value=[];detailError.value='';detailTab.value='policy';eventPage.value=1;try{const r=await catalogGet('creators',id);if(seq===detailSeq)detail.value=r.data}catch(e){if(seq===detailSeq)detailError.value=e.message}finally{if(seq===detailSeq)detailLoading.value=false}}
async function loadDetailTab(){if(detailTab.value==='points')await loadPoints()}
async function loadPoints(){if(!detail.value)return;const id=detail.value.creator.userId,seq=++pointsSeq;points.value=null;events.value=[];detailError.value='';try{const [a,e]=await Promise.all([catalogList(`creators/${id}/points`),catalogList(`creators/${id}/point-events`,{pageNum:eventPage.value,pageSize:eventSize.value})]);if(seq===pointsSeq && detail.value?.creator.userId===id){points.value=a.data;events.value=e.rows;eventTotal.value=e.total}}catch(e){if(seq===pointsSeq)detailError.value=e.message}}
function clearPassword(){form.value.initialPassword=''}
function closeDialog(done){if(!saving.value){clearPassword();++optionSeq;done()}}
function open(action,row={}){clearPassword();++optionSeq;op.value=action;formError.value='';options.value=[];form.value={id:row.userId||'',revision:row.revision||'',userName:'',nickName:'',initialPassword:'',reason:'',status:row.status||'active',validUntil:row.validUntil?date(row.validUntil):'',maxConcurrentNodes:Math.min(row.maxConcurrentNodes||1,limits.value?.maxConcurrentNodes||1),maxPendingRuns:Math.min(row.maxPendingRuns||10,limits.value?.maxPendingRuns||1),maxDailySubmissions:row.maxDailySubmissions||1000,maxStorageBytes:row.maxStorageBytes||'1073741824',modelIds:[],kind:'grant',amount:'',available:row.available||'0'};dialog.value=true}
async function openModels(id){try{const r=await catalogGet('creators',id);open('creator.models',r.data.creator);form.value.modelIds=[...r.data.modelIds];await searchModels('')}catch(e){error.value=e.message}}
async function openPoints(id){try{const r=await catalogList(`creators/${id}/points`);open('points.adjust',r.data)}catch(e){error.value=e.message}}
async function searchModels(name=''){const seq=++optionSeq;optionsLoading.value=true;try{const r=await catalogList('creator-model-options',{name,pageSize:100});if(seq===optionSeq){const kept=options.value.filter(o=>form.value.modelIds.includes(o.modelId));const byId=new Map([...kept,...r.rows].map(o=>[o.modelId,o]));for(const id of form.value.modelIds)if(!byId.has(id))byId.set(id,{modelId:id,name:'已授权模型'});options.value=[...byId.values()]}}catch(e){if(seq===optionSeq)formError.value=e.message}finally{if(seq===optionSeq)optionsLoading.value=false}}
function forgetPending(){pending.value=null;try{sessionStorage.removeItem(pendingKey)}catch{ElMessage.warning('已完成，但浏览器记录未清除，下次可核对原编号')}}
async function completed(){forgetPending();dialog.value=false;clearPassword();ElMessage.success('已保存');await loadList();if(detailOpen.value && detail.value)await showDetail(detail.value.creator.userId)}
async function submit(){if(saving.value)return;formError.value='';let w;try{w=creatorPayload(op.value,form.value,limits.value)}catch(e){formError.value=e.message;return}const meta=pending.value||creatorPending(op.value,form.value);if(meta.op!==op.value || meta.id!==(op.value==='creator.create'?'':form.value.id) || meta.revision!==(op.value==='creator.create'?'':form.value.revision)){formError.value='请先核对原操作，不能更换目标或版本';return}w.data.requestId=meta.requestId;try{sessionStorage.setItem(pendingKey,JSON.stringify(meta))}catch{formError.value='无法保存操作编号，本次未提交';clearPassword();w.data.initialPassword='';return}pending.value=meta;saving.value=true;try{await catalogWrite(w.method,w.path,w.data);await completed()}catch(e){formError.value=e.message;if(e.code>=400 && e.code<500){try{await catalogAction(meta.requestId);await completed()}catch(checkError){if(checkError.code===404)forgetPending()}}}finally{clearPassword();w.data.initialPassword='';saving.value=false}}
async function checkPending(){if(!pending.value)return;checking.value=true;error.value='';try{await catalogAction(pending.value.requestId);await completed()}catch(e){error.value=e.code===404?'尚无已完成记录，请保留原编号，重填原内容后重试。':e.message}finally{checking.value=false}}
async function recoverPending(){const p=pending.value;if(!p)return;try{try{await catalogAction(p.requestId);await completed();return}catch(e){if(e.code!==404)throw e}if(p.op==='creator.create')open(p.op);else if(p.op==='creator.models')await openModels(p.id);else if(p.op==='points.adjust')await openPoints(p.id);else{const r=await catalogGet('creators',p.id);open(p.op,r.data.creator)}form.value.id=p.id;form.value.revision=p.revision}catch(e){error.value=e.message}}
onMounted(async()=>{try{limits.value=(await catalogList('creator-limits')).data}catch(e){error.value=e.message}await loadList()})
onBeforeUnmount(()=>{clearPassword();++listSeq;++detailSeq;++pointsSeq;++optionSeq})
</script>
<style scoped>
.heading{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:16px}.heading h2{margin:0 0 8px;font-size:22px}.heading p{margin:0}.muted,.heading p{color:var(--el-text-color-secondary);font-size:13px;line-height:1.7}.notice,.query{margin-top:14px}.notice{margin-bottom:14px}.hint{width:100%;margin-top:4px}.inline-hint{margin-left:12px;color:var(--el-text-color-secondary)}.detail{min-height:130px}.detail :deep(.el-descriptions){overflow-wrap:anywhere}@media(max-width:600px){.heading{flex-direction:column;align-items:flex-start}.query :deep(.el-form-item){display:flex;margin-right:0}}
</style>
